REPORT_DEF = {10: ["LotID", "RecipeID"], 20: ["ChamberPressure", "RFPower"]}
CEID_NAME = {301: "ProcessStart"}
msg = {"DATAID": 1, "CEID": 301,
       "RPT": [{"RPTID": 10, "V": ["LOT001", "ETCH_A"]},
               {"RPTID": 20, "V": [3.2, 750]}]}
row = {"event": CEID_NAME[msg["CEID"]]}
for r in msg["RPT"]:
    row.update(zip(REPORT_DEF[r["RPTID"]], r["V"]))
print(row)
